/usr/bin/bash -lc "sed -n '280,560p' src/click/testing.py
sed -n '320,760p' tests/test_testing.py
python - <<'PY'
import io
for action in ('detach', 'close_then_detach'):
    b = io.BytesIO()
    w = io.TextIOWrapper(b, encoding='utf-8')
    print(action)
    try:
        if action == 'detach':
            w.write('x')
            print('detached is b', w.detach() is b, 'b.closed', b.closed, 'value', b.getvalue())
            for label, fn in [('closed', lambda: w.closed), ('close-again', w.close), ('buffer', lambda: w.buffer)]:
                try: print(label, fn())
                except Exception as e: print(label, type(e).__name__, str(e))
        else:
            w.close()
            print('b.closed', b.closed)
            print(w.detach())
    except Exception as e:
        print(type(e).__name__, str(e))
PY

